local dumbbassnigFX = {}
function dumbbassnigFX.Create(class, props, parent)
local obj = Instance.new(class)
for k, v in pairs(props) do obj[k] = v end
if parent then obj.Parent = parent end
return obj
end
function dumbbassnigFX.Tween(obj, props, dur, style, dir)
local t = dumbbassnigTS:Create(obj, TweenInfo.new(dur or 0.35, style or Enum.EasingStyle.Exponential, dir or Enum.EasingDirection.Out), props)
t:Play()
return t
end
function dumbbassnigFX.MakeDraggable(topbar, main)
local dragging, dragStart, startPos
topbar.InputBegan:Connect(function(input)
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
dragging = true
dragStart = input.Position
startPos = main.Position
input.Changed:Connect(function()
if input.UserInputState == Enum.UserInputState.End then dragging = false end
end)
end
end)
dumbbassnigUIS.InputChanged:Connect(function(input)
if (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and dragging then
local delta = input.Position - dragStart
dumbbassnigFX.Tween(main, {Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)}, 0.1, Enum.EasingStyle.Linear)
end
end)
end
function dumbbassnigFX.SetBlur(enabled)
local b = dumbbassnigLighting:FindFirstChild("FXPremiumBlur")
if enabled then
if not b then
b = dumbbassnigFX.Create("BlurEffect", {Name = "FXPremiumBlur", Size = 0}, dumbbassnigLighting)
end
dumbbassnigFX.Tween(b, {Size = 25}, 0.5)
else
if b then
dumbbassnigFX.Tween(b, {Size = 0}, 0.5)
task.delay(0.5, function() b:Destroy() end)
end
end
end
